def sin_palabra_restringido(linea):
    """La línea sin la palabra que la declara: «**restringido**: márgenes» → «márgenes»."""
    return re.sub(r"^[\W_]*restringid[oa]\b[*_»\"”'’\s]*[:—–,-]?\s*", "", linea or "", flags=re.I).strip()
